// Des: Unit tests for pulse, once parse, due window
// Flo: parse pulse and once > assert value or error > check window
// I/O: schedule strings + Local > ms, stamp, bool
// ===================================================================
const std = @import("std"); const time = @import("tk-task-time.zig");
const tszz = std.testing; const Local = time.Local; const CronError = time.CronError; const PulseError = time.PulseError; const OnceError = time.OnceError; const SolarError = time.SolarError; const SolarEvent = time.SolarEvent; const ONCE_LATE_WINDOW_MIN = time.ONCE_LATE_WINDOW_MIN;
const daysFromCivil = time.daysFromCivil; const civiDays = time.civiDays; const localFromMinuteStamp = time.localFromMinuteStamp; const yearLeap = time.yearLeap; const montDays = time.montDays; const parseCron = time.parseCron; const cronMatch = time.cronMatch; const nextCronMinute = time.nextCronMinute; const parsePulse = time.parsePulse; const parseOnce = time.parseOnce; const onceDue = time.onceDue; const parseSolar = time.parseSolar; const sunzTime = time.sunzTime;
test "parsePulse floors to seconds and accepts units" { try tszz.expectEqual(@as(u64, 5000), try parsePulse("5000")); try tszz.expectEqual(@as(u64, 5000), try parsePulse("5s")); try tszz.expectEqual(@as(u64, 300000), try parsePulse("5m")); try tszz.expectEqual(@as(u64, 3600000), try parsePulse("1h")); try tszz.expectEqual(@as(u64, 1000), try parsePulse("1999")); try tszz.expectError(PulseError.TooSmall, parsePulse("999")); try tszz.expectError(PulseError.TooSmall, parsePulse("0")); try tszz.expectError(PulseError.BadNumber, parsePulse("abc")); try tszz.expectError(PulseError.BadNumber, parsePulse("")); try tszz.expectError(PulseError.BadNumber, parsePulse("s")); try tszz.expectError(PulseError.BadNumber, parsePulse("99999999999999999999h")); }
test "parseOnce handles every documented shape" { const base = daysFromCivil(2026, 7, 14) * 1440; try tszz.expectEqual(base, try parseOnce("260714")); try tszz.expectEqual(base + 2 * 60, try parseOnce("260714_02")); try tszz.expectEqual(base + 2 * 60 + 30, try parseOnce("260714_0230")); try tszz.expectEqual(base + 2 * 60 + 30, try parseOnce("260714-023045")); }
test "parseOnce rejects impossible dates and times" { try tszz.expectError(OnceError.BadFormat, parseOnce("2607")); try tszz.expectError(OnceError.BadFormat, parseOnce("26071x")); try tszz.expectError(OnceError.BadDate, parseOnce("261301")); try tszz.expectError(OnceError.BadDate, parseOnce("260732")); try tszz.expectError(OnceError.BadDate, parseOnce("260230")); try tszz.expectError(OnceError.BadTime, parseOnce("260714_25")); try tszz.expectError(OnceError.BadTime, parseOnce("260714_0260")); try tszz.expectError(OnceError.BadFormat, parseOnce("260714x02")); try tszz.expectError(OnceError.BadFormat, parseOnce("260714_023")); _ = try parseOnce("240229"); try tszz.expectError(OnceError.BadDate, parseOnce("260229")); }
test "onceDue fires in its window, never for an ancient task" { const targ = daysFromCivil(2026, 8, 17) * 1440 + 12 * 60; try tszz.expect(!onceDue(targ, localFromMinuteStamp(targ - 1))); try tszz.expect(onceDue(targ, localFromMinuteStamp(targ))); try tszz.expect(onceDue(targ, localFromMinuteStamp(targ + ONCE_LATE_WINDOW_MIN))); try tszz.expect(!onceDue(targ, localFromMinuteStamp(targ + ONCE_LATE_WINDOW_MIN + 1))); try tszz.expect(!onceDue(targ, localFromMinuteStamp(targ + 90 * 1440))); }
